  1	#!/usr/bin/env bats
  2	# validate-artifact.sh --type sprint: the '### Seams Under Test' rule gated on the plan's
  3	# header **Date:** (grimoires/loa/sdd.md D-7.2; SEAMS_REQUIRED_FROM=2026-10-13).
  4	
  5	setup() {
  6	    PROJECT_ROOT="$(cd "${BATS_TEST_DIRNAME}/../.." && pwd)"
  7	    SCRIPT="${PROJECT_ROOT}/.claude/scripts/validate-artifact.sh"
  8	    T="${BATS_TEST_TMPDIR}"
  9	}
 10	
 11	# A plan with two sprint blocks; $1 = header date line (may be empty), $2 = seams in sprint 1
 12	# (yes|no|empty), $3 = seams in sprint 2 (yes|no|empty).
 13	seams_block() {
 14	    case "$1" in
 15	        yes) printf '### Seams Under Test\n| Seam | Catches | Misses | Prior art |\n|------|---------|--------|-----------|\n| `tool.sh` exit code | a wrong exit | prose | new |\n\n' ;;
 16	        empty) printf '### Seams Under Test\n| Seam | Catches | Misses | Prior art |\n|------|---------|--------|-----------|\n\n' ;;
 17	        *) ;;
 18	    esac
 19	}
 20	sprint_body() {
 21	    printf '### Sprint Goal\ng\n\n### Deliverables\n- [ ] d\n\n### Acceptance Criteria\n- [ ] c\n\n'
 22	    printf '### Technical Tasks\n- [ ] Task %s → **[G-1]**\n\n' "$2"
 23	    seams_block "$1"
 24	    printf '### Dependencies\n- none\n\n### Security Considerations\n- none\n\n'
 25	    printf '### Risks & Mitigation\n| Risk | Probability | Impact | Mitigation |\n|---|---|---|---|\n| r | Low | Low | m |\n\n'
 26	    printf '### Success Metrics\n- m\n\n'
 27	}
 28	plan() {
 29	    printf '# Sprint Plan: x\n\n**Version:** 1.0\n'
 30	    [[ -n "$1" ]] && printf '**Date:** %s\n' "$1"
 31	    printf '**Author:** test\n\n---\n\n'
 32	    printf '## Sprint 1: Foundation\n\n'; sprint_body "$2" "1.1"
 33	    printf '## Sprint 2 (Final): Wrap-up\n\n'; sprint_body "$3" "2.E2E: End-to-End Goal Validation"
 34	    printf '## Appendix\n\n| Goal ID | Goal |\n|---|---|\n| G-1 | thing |\n'
 35	}
 36	
 37	@test "SEAMS-1 a plan dated 2026-10-13 without the block fails and names each sprint missing it" {
 38	    plan 2026-10-13 yes no > "$T/sprint.md"
 39	    run "$SCRIPT" --type sprint --file "$T/sprint.md"
 40	    [ "$status" -eq 1 ]
 41	    [[ "$output" == *"Sprint 2 (Final): Wrap-up (line"*"has no '### Seams Under Test' table"* ]]
 42	    [[ "$output" != *"Sprint 1: Foundation (line"*"Seams Under Test"* ]]
 43	}
 44	
 45	@test "SEAMS-2 the same plan with the block in every sprint passes without a seams WARN" {
 46	    plan 2026-10-13 yes yes > "$T/sprint.md"
 47	    run "$SCRIPT" --type sprint --file "$T/sprint.md"
 48	    [ "$status" -eq 0 ] || { echo "$output"; return 1; }
 49	    [[ "$output" != *"Seams Under Test"* ]]
 50	}
 51	
