 75	    { plan "" no no; printf '\n## Notes\n\n**Date:** 2026-12-01\n'; } > "$T/sprint.md"
 76	    run "$SCRIPT" --type sprint --file "$T/sprint.md"
 77	    [ "$status" -eq 0 ] || { echo "$output"; return 1; }
 78	    [[ "$output" == *"WARN: undated plan"* ]]
 79	}
