 86	        printf '## Appendix\n\n| Goal ID | Goal |\n|---|---|\n| G-1 | thing |\n'
 87	    } > "$T/sprint.md"
 88	    run "$SCRIPT" --type sprint --file "$T/sprint.md"
 89	    [ "$status" -eq 1 ]
 90	    [[ "$output" == *"Sprint 2 (Final): Wrap-up (line"*"Seams Under Test"* ]]
 91	}
 92	
