 94	    [ -f "$PROJECT_ROOT/grimoires/loa/sprint.md" ] || skip "no live sprint plan in this checkout"
 95	    grep -q '^\*\*Date:\*\* 2026-10-1[3-9]' "$PROJECT_ROOT/grimoires/loa/sprint.md" || skip "the live plan is not the cycle-128 plan"
 96	    run "$SCRIPT" --type sprint --file "$PROJECT_ROOT/grimoires/loa/sprint.md"
 97	    [ "$status" -eq 0 ] || { echo "$output"; return 1; }
 98	    [[ "$output" != *"Seams Under Test"* ]]
 99	}
100	
101	@test "SEAMS-9 the archived cycle-127 plan (dated 2026-10-07) gains only a WARN from the rule" {
102	    local f="$PROJECT_ROOT/tests/fixtures/sprint-seams/cycle-127-sprint.md"
103	    run "$SCRIPT" --type sprint --file "$f"
104	    [[ "$output" == *"WARN: 2026-10-07 plan: 1 sprint block(s) without a '### Seams Under Test' table"* ]]
105	    [[ "$output" != *"has no '### Seams Under Test' table with"* ]]
106	    # The plan predates the template's Risks & Mitigation / Success Metrics sections and fails
107	    # on those alone, exactly as it did before the seams rule; the rule adds no violation.
108	    local others
109	    others="$(grep -v '^WARN\|^INFO' <<< "$output" | grep -vc "missing required section '### \(Risks & Mitigation\|Success Metrics\)'" || true)"
110	    [ "$others" -eq 0 ]
111	}
112	
113	@test "SEAMS-10 the shipped sprint template carries the block in each full sprint block" {
114	    local t="$PROJECT_ROOT/.claude/skills/planning-sprints/resources/templates/sprint-template.md"
115	    [ "$(grep -c '^### Seams Under Test$' "$t")" -eq 2 ]
116	    [ "$(grep -c '^| Seam | Catches | Misses | Prior art |$' "$t")" -eq 2 ]
117	}

